
// ===== p183 : d'après le Portail de l'esclavage de La Réunion (Département) — résistances, origines des esclaves, traite illégale, après l'abolition =====
{const ok=[{n:'Continuer',d:'',fx:{},hist:1}],SRC='Portail de l’esclavage de La Réunion (Département de La Réunion), ';
 const A=(id,y,an,t,b,h,o)=>{const e={y,si:()=>S,tag:'Archive',an,nat:'Fait historique. Les choix sont inventés pour le jeu.',t,v:'Ce que gardent les archives.',h:SRC+h,o:o||ok};if(typeof b==='function')Object.defineProperty(e,'b',{get:b,enumerable:true});else e.b=b;EV[id]=e};
 A('kivis1671',1672,'1671-1674','Les colons qui fuient le gouverneur',function(){return 'Sous le gouverneur La Hure, des habitants n’en peuvent plus de sa tyrannie : ils montent se retrancher au Piton de Grande Anse. On les appelle les « kivis ». En 1674, le vice-roi La Haye, de passage, fait rappeler les déserteurs. Avant les esclaves, ce sont des colons qui ont fui vers la montagne.'},'« Résistances à l’esclavage » : La Hure (1671-1674), retraite au Piton de Grande Anse, rappel des déserteurs par La Haye en novembre 1674, ramenés par Jacques Launay.');
 A('complot1705',1705,'1705','Le complot de Saint-Paul','À Saint-Paul, un complot d’esclaves est découvert. Sébastien, Samban et Mathieu sont condamnés à être brûlés vifs. Un an plus tôt, les premiers esclaves s’étaient enfuis par la mer.','« Résistances à l’esclavage » : premières fuites par mer en 1704 ; complot de Saint-Paul en 1705.');
 A('traiteOuest1729',1729,'1729-1731','Des navires d’Afrique de l’Ouest',function(){return 'Deux cents captifs arrivent de Juda (Ouidah), puis 76 et 188 de Gorée. Dans l’île, on entend maintenant des langues de Madagascar, de l’Inde et de toute l’Afrique. '+'Pondichéry envoie aussi des esclaves indiens depuis 1728.'},'« D’où provenaient les esclaves de Bourbon ? » : 200 esclaves de Juda en 1729, 76 puis 188 de Gorée en 1730-1731 ; arrivées depuis Pondichéry à partir de 1728.');
 A('cafres1739',1739,'20 mars 1739','Neuf détachements à la Plaine des Cafres',function(){return S&&S.voieC?'La Bourdonnais fait ratisser la Plaine des Cafres par neuf détachements à la fois. Ils trouvent 36 ajoupas… tous vides.':'Neuf détachements montent ensemble à la Plaine des Cafres. Ils trouvent 36 ajoupas, tous vides : les guetteurs avaient vu venir les fusils.'},'« Résistances à l’esclavage » : ratissage du 20 mars 1739 à la Plaine des Cafres, neuf détachements, 36 ajoupas découverts vides.');
 A('raharianne1751',1751,'1751','Mafac et Raharianne',function(){return 'Dans les Hauts, le chasseur François Mussard tue Mafac et sa femme Raharianne. Les récits feront plus tard de Raharianne une guerrière. Les archives, elles, ne gardent que sa mort.'},'« La femme dans le marronnage à La Réunion » et « Résistances » : archive de 1751 (Mussard). Raharianne et Sarlave sont les seules femmes marronnes attestées par des documents ; Héva, Simangalove et d’autres relèvent surtout de la légende.');
 A('droman1753',1753,'juin 1753','Les chiens du Bras de la Plaine',function(){return S&&S.voieC?'Le détachement de Patrice Droman attaque un camp au Bras de la Plaine. Il en revient sans ses chiens : 31 bêtes tuées par les marrons.':'Le détachement de Patrice Droman attaque au Bras de la Plaine. Les marrons tiennent : 31 chiens de chasse ne redescendront pas.'},'« Résistances à l’esclavage » : en juin 1753, le détachement de Patrice Droman perd 31 chiens lors d’une attaque au Bras de la Plaine.');
 A('mozambique1770',1770,'1770-1802','La traite des côtes d’Afrique de l’Est',function(){return 'Les navires vont maintenant chercher les captifs à Quiloa, sur la côte d’Afrique de l’Est, puis à Zanzibar. Au début de la période royale, les esclaves venus d’Afrique, les « Cafres », sont cinq fois plus nombreux que les Malgaches.'},'« D’où provenaient les esclaves de Bourbon ? » : Quiloa foyer principal 1770-1794, Zanzibar à partir de 1802 ; pour 1815-1832, 43 % des esclaves d’origine connue viennent d’Afrique de l’Est, 36 % de Madagascar, 15 % d’Afrique de l’Ouest, 6 % de la région du Cap. En tout, environ 200 000 personnes déportées vers l’île (estimation).');
 A('grimaud1788',1788,'octobre 1788','Cent fuyards au-dessus de Saint-Louis',function(){return S&&S.voieC?'Au-dessus de l’habitation Grimaud, à Saint-Louis, une centaine d’esclaves s’évadent d’un coup. Les détachements ne savent où chercher.':'Au-dessus de l’habitation Grimaud, à Saint-Louis, une centaine d’esclaves s’évadent ensemble. Les Hauts doivent nourrir cent bouches de plus.'},'« Résistances à l’esclavage » : en octobre 1788, une centaine d’esclaves s’évadent au-dessus de l’habitation Grimaud, à Saint-Louis.',
  [{n:'Les accueillir',d:'+3 personnes, vivres -6, traque +6.',fx:{gens:3,vivres:-6,traque:6},hist:1},{n:'Les envoyer vers d’autres camps',d:'Cohésion +2.',fx:{coh:2}}]);
 A('adonis1799',1799,'octobre 1799','Le complot de Sainte-Rose','À Sainte-Rose, l’esclave malgache Adonis dénonce un complot : près de 500 esclaves s’apprêteraient à se soulever. Vrai ou exagéré, le chiffre fait trembler les habitations de l’Est.','« Résistances à l’esclavage » : complot dénoncé à Sainte-Rose en octobre 1799 par l’esclave malgache Adonis, qui parle de près de 500 esclaves.');
 A('jacob1801',1801,'février 1801','Le camp de Jacob',function(){return 'Un marron capturé révèle un camp de quinze ou seize personnes dans les Hauts de Saint-Denis. Leurs chefs se font appeler Jacob, Saint-Perne et Madame Jacob.'},'« Résistances à l’esclavage » : février 1801, camp de 15 à 16 marrons dans les Hauts de Saint-Denis, chefs Jacob, Saint-Perne et Madame Jacob.');
 A('galets1804',1804,'1804','Vingt Malgaches à la rivière des Galets','À peine débarqués, vingt Malgaches s’échappent et s’installent près de la rivière des Galets. Ils n’ont jamais travaillé un seul jour sur une habitation.','« Résistances à l’esclavage » : en 1804, vingt Malgaches s’évadent après leur débarquement et s’installent près de la rivière des Galets.');
 A('fantaisie1823',1823,'1821-1823','Fantaisie à Paris',function(){return 'Fantaisie, un jeune homme né en Afrique de l’Est, esclave de la famille Desbassayns, débarque en France en 1821 avec son maître. À Paris, il quitte la maison et va vivre chez un musicien libre. Sa maîtresse le fait rechercher ; mais en France, le sol rend libre, et le ministre décide en novembre 1823 qu’« il n’y a rien à faire ». Fantaisie reste libre.'},'« Fantaisie, esclave des Desbassayns, pose le pied sur le sol libre à Paris » : arrivé à Rochefort le 13 avril 1821, il quitte la famille à l’automne 1823 ; en novembre 1823, le Conseil des ministres renonce à le renvoyer. En mars 1824, le transport d’esclaves vers la France est interdit.');
 A('malheur1829',1829,'vers 1829','La dernière grande bataille de l’Îlette à Malheur',function(){return S&&S.voieC?'Le détachement de Léonard Guichard attaque l’Îlette à Malheur, où vivent une quarantaine de marrons. Il perd deux hommes ; vingt-cinq marrons sont tués. Vingt ans plus tard, on voit encore leurs tombes.':'À l’Îlette à Malheur, une quarantaine de marrons vivent depuis des années. Le détachement de Léonard Guichard les attaque : vingt-cinq tombent, deux chasseurs aussi. Les survivants montent plus haut. Vingt ans plus tard, leurs tombes sont toujours là.'},'« Résistances à l’esclavage » : vers 1829, dernière grande lutte à l’îlette à Malheur ; une quarantaine de marrons, détachement de Léonard Guichard, deux hommes perdus, 25 marrons tués ; tombeaux encore visibles en 1849.');
 A('stAndre1836',1836,'7 novembre 1836','Le prix d’une dénonciation','Guillaume et Augustin ont révélé le complot de Saint-André. On leur donne la liberté et une pension de 360 francs. Quatre ans plus tôt, un autre complot avait été découvert à Saint-Benoît.','« Résistances à l’esclavage » : complot de Saint-Benoît en 1832 ; le 7 novembre 1836, Guillaume et Augustin reçoivent la liberté et une pension de 360 francs pour avoir révélé le complot de Saint-André.');
 A('apres1849',1849,'1849-1857','Libres, mais engagés',function(){return 'Les nouveaux libres doivent signer un contrat d’engagement : sans contrat, on les traite en vagabonds et on les envoie aux ateliers de travail forcé. Leur salaire a été réduit des deux tiers. La fête de l’abolition est bannie de l’espace public : on la célèbre en famille.'},'« L’abolition de l’esclavage à La Réunion » : engagement obligatoire, salaires réduits des deux tiers, souvenir du 20 décembre limité aux familles ; de 1849 à 1857, le coût d’un contrat d’engagement passe d’un peu moins de 200 à 1 100 francs.');
 A('memoire1983',1983,'1983','Le 20 décembre, jour férié','Pour la première fois, le 20 décembre devient un jour officiel : la fête de l’abolition, la « Fèt Kaf », sort enfin des familles pour descendre dans la rue.','« Après l’abolition » : aucune commémoration officielle de 1870 à 1936 ; en 1983, les régions d’outre-mer peuvent célébrer officiellement leur date d’abolition ; en 2001, la France reconnaît la traite et l’esclavage comme crime contre l’humanité.');
 try{if(EV.traite181)EV.traite181.h+=' Portail de l’esclavage : de 1817 à 1831, environ 50 000 captifs introduits en fraude (38 500 pour 1817-1830 selon Hubert Gerbeau) ; en 1819, la goélette « Joséphine » amène 117 captifs de Madagascar ; la loi du 4 mars 1831 fait de la traite un crime ; dernière condamnation en 1832, la trentième depuis 1818.'}catch(e){}
}
{const ok=[{n:'Continuer',d:'',fx:{},hist:1}],SRC='Portail de l’esclavage de La Réunion (Département de La Réunion), ';
 const A=(id,y,an,t,b,h,o)=>{const e={y,si:()=>S,tag:'Archive',an,nat:'Fait historique. Les choix sont inventés pour le jeu.',t,v:'Ce que gardent les archives.',h:SRC+h,o:o||ok};if(typeof b==='function')Object.defineProperty(e,'b',{get:b,enumerable:true});else e.b=b;EV[id]=e};
 A('libresTraque1740',1740,'depuis 1735','La prime du Libre',function(){return S&&S.voieC?'Depuis La Bourdonnais, un Libre de couleur qui capture ou tue un marron reçoit un esclave en récompense. Les Libres de couleur ne sont qu’une petite part des libres de l’île, et la police de la couleur les surveille de près.':'Dans les Hauts, on se méfie aussi des Libres de couleur : depuis La Bourdonnais, celui qui ramène un marron, mort ou vif, reçoit un esclave en récompense.'},'« Les Libres de couleur à Bourbon » : depuis Mahé de La Bourdonnais, un Libre qui capture ou tue un marron reçoit un esclave en récompense ; à la fin de la période royale, les Libres de couleur sont 11 % des libres de Bourbon (43 % à Saint-Domingue).');
 A('regBourbon1812',1812,'4 octobre 1812','Le régiment des affranchis','Sous l’occupation anglaise, un régiment de Bourbon défile à Port-Louis : 685 hommes, dont plus de 650 sont des affranchis. On leur a promis la liberté en échange du fusil.','« Les Libres de couleur à Bourbon » : régiment de Bourbon de l’armée anglaise, 685 hommes dont 28 officiers et 89 sous-officiers ; selon Danielle Miloche-Baty, 653 soldats étaient des affranchis ; défilé à Port-Louis le 4 octobre 1812. La promesse de liberté contre le service est la lecture du jeu.');
 A('jourAn1813',1813,'janvier 1813','Le premier de l’an',function(){return 'Au premier de l’an, la coutume veut que les esclaves viennent présenter leurs vœux au maître : on danse, même sous la pluie, au son des tambours. Le maître donne des étrennes, un vêtement, de la limonade. '+(S&&!S.voieC?'Au camp, un marron capturé dira plus tard qu’il comptait le temps en « fêtes banane » : le nouvel an, c’est la seule date que tout le monde connaît.':'')},'« Les esclaves et le jour de l’an » : janvier 1813, les esclaves de Grinne dansent sous la pluie chez Renoyal de Lescouble (Journal d’un colon de l’île Bourbon) ; vœux et étrennes ; le marron Jouan situe la durée de sa fuite par la « fête banane » (ADR, 37 C).');
 A('campVillele1845',1845,'1845','Une journée sur l’habitation de Saint-Gilles',function(){return 'La cloche sonne : les bandes partent aux champs, il ne reste au camp que deux gardiens. Près de la moitié des esclaves sont « noirs de pioche ». Le dimanche, il faut encore nettoyer jusqu’à une heure ; le repos ne commence que l’après-midi. Depuis que la Chapelle Pointue est bâtie, on s’y marie plus souvent.'},'« La vie quotidienne des esclaves sur la propriété Desbassayns » : en 1845, les « noirs de pioche » font près de 48 % des esclaves dont la fonction est connue ; départ en bandes au son de la cloche ; repos le dimanche après-midi seulement ; mariages religieux plus fréquents à partir de 1843, avec la Chapelle Pointue (construite en 1841) ; châtiments : fouet, prison, travail du dimanche.');
 try{if(EV.mDesb)EV.mDesb.h=(EV.mDesb.h?EV.mDesb.h+' ':'')+'Portail de l’esclavage (« Madame Desbassayns ») : née le 3 juillet 1755, mariée à presque quinze ans en 1770, morte le 4 février 1846. De son vivant, on l’appelle la « Seconde Providence » ; la légende noire naît vers 1910 et revient dans les années 1970. Pour l’historien, aucune preuve ne permet de trancher entre les deux légendes, et son personnage sert parfois de bouc émissaire qui fait oublier les autres maîtres.'}catch(e){}
 try{if(EV.reg1832)EV.reg1832.h+=' Portail de l’esclavage : l’ordonnance du 12 juillet 1832 donne enfin un nom de famille à l’affranchi, inscrit à l’état civil dans les mêmes registres que les Blancs.'}catch(e){}
}
try{if(EV.houat1844)EV.houat1844.h+=' Portail de l’esclavage (« Les Libres de couleur à Bourbon ») : enseignant gratuit, musicien et abolitionniste, il est condamné à la déportation le 3 août 1836, gracié le 18 juin 1837 mais exilé quand même ; la Cour de cassation annulera sa condamnation.'}catch(e){}
// ===== les journaux de l'île (d'après « Imprimerie et presse à La Réunion », entreprises-coloniales.fr) =====
{const ok=[{n:'Continuer',d:'',fx:{},hist:1}],SRC='« Imprimerie et presse à La Réunion » (entreprises-coloniales.fr) : ';
 const A=(id,y,an,t,b,h)=>{const e={y,si:()=>S,tag:'Archive',an,nat:'Fait historique.',t,v:'Les nouvelles s’impriment.',h:SRC+h,o:ok};if(typeof b==='function')Object.defineProperty(e,'b',{get:b,enumerable:true});else e.b=b;EV[id]=e};
 A('impr1791',1791,'1791','La première imprimerie','Une presse arrive à Bourbon. Pour la première fois, on peut imprimer dans l’île les lois, les avis et les annonces, au lieu d’attendre ceux de l’île de France.','première imprimerie de l’île Bourbon en 1791.');
 A('gazette1804',1804,'1804','Le premier journal','À Saint-Denis paraît la Gazette de l’Isle de la Réunion, imprimée par Boyer avec la permission du général Decaen. Elle parle pour le gouvernement : prix, arrêtés, navires attendus… et esclaves en fuite signalés.','Gazette de l’Isle de la Réunion, premier journal imprimé à Saint-Denis en 1804 (E. Boyer, privilège du général Decaen) ; devient Gazette de l’Île Bourbon en 1817. Les avis d’esclaves marrons dans les journaux coloniaux sont un fait général ; leur présence dans ce titre précis n’est pas vérifiée ici.');
 A('salazien1830',1830,'1830-1833','Le Salazien, journal clandestin',function(){return 'Un journal républicain circule sous le manteau, prudemment daté de Maurice : il s’appelle Le Salazien, du nom du cirque le plus sauvage de l’île. Il est saisi le 27 juillet 1833 ; ses auteurs sont condamnés à cent francs d’amende chacun.'+(S&&!S.voieC?' Au camp, on rit qu’un journal de la ville porte le nom des Hauts.':'')},'Le Salazien (1830-1833), journal républicain clandestin, saisi le 27 juillet 1833, promoteurs condamnés par défaut à cent francs d’amende chacun.');
 A('cripublic1848',1848,'1848','Le Cri public','Pendant que l’abolition approche, Alexandre de La Serve fait paraître en cachette Le Cri public. Le Journal du Commerce, fondé deux ans plus tôt, est devenu la voix des républicains.','Journal du Commerce fondé en 1846 (frères Delval, Prosper de Greslan), organe du parti républicain ; Cri public, journal clandestin d’Alexandre de La Serve en 1848 ; la même année naît le Moniteur de l’île Bourbon.');
 A('creole1882',1882,'1882','Le journal à dix centimes','Élysée Pélagaud lance Le Créole, petit format à dix centimes. Le journal n’est plus réservé aux riches : on le lit à voix haute dans les boutiques.','Le Créole d’Élysée Pélagaud (1882), petit format à dix centimes, début de la presse à bon marché. La lecture à voix haute dans les boutiques est une image du jeu.');
}

